{
  "title": "tBregs and Tumour Growth",
  "perWatchSecond": 5,
  "levels": [
    {
      "kind": "hook",
      "title": "Impact of tBreg-Induced Treg Growth",
      "goal": "Explore how the rate at which tBregs stimulate Treg growth influences tumour expansion.",
      "control": {
        "parameter": "mB",
        "label": "tBreg‑induced Treg growth rate",
        "lowEnd": "0 (no stimulation)",
        "highEnd": "6e-8 (doubled)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if tBreg‑induced Treg growth is doubled?",
        "parameter": "mB",
        "value": 6e-08
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 67,
        "time": 67,
        "relation": "higher",
        "by": 5
      },
      "effect": "With mB doubled, the tumour population at day 67 is at least 5 units higher than with the original rate.",
      "prediction": {
        "prompt": "Predict whether tumour size at day 67 will be higher or lower when mB is doubled.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "tBregs promote tumour growth",
        "quote": "if tBregs exist in the body, a sufficiently large number of tBregs can cause the breast tumour to reach its carrying capacity, regardless of the rate of NK-induced breast cancer cell death."
      },
      "carryForward": "Use the same parameter set for the next level."
    },
    {
      "kind": "background",
      "title": "Role of Tumour‑Induced tBreg Generation",
      "goal": "Examine how the rate at which tumour cells generate tBregs affects long‑term tumour burden.",
      "control": {
        "parameter": "mT",
        "label": "Tumour‑induced tBreg generation rate",
        "lowEnd": "0 (no generation)",
        "highEnd": "1e-14 (doubled)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if tumour‑induced tBreg generation is doubled?",
        "parameter": "mT",
        "value": 1e-14
      },
      "difference": {
        "compartment": "t",
        "summary": "total",
        "at": null,
        "time": 67,
        "relation": "higher",
        "by": 10
      },
      "effect": "Doubling mT increases the cumulative tumour cell count over 67 days by at least 10 units.",
      "prediction": {
        "prompt": "Will the total tumour cell count over 67 days be higher or lower when mT is doubled?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": null,
      "carryForward": "Keep all other parameters unchanged."
    },
    {
      "kind": "idea",
      "title": "Effect of NK Cell Killing Efficiency",
      "goal": "Assess how varying the NK‑cell killing rate changes tumour dynamics.",
      "control": {
        "parameter": "c",
        "label": "NK‑induced tumour death rate",
        "lowEnd": "1e-10 (half the original)",
        "highEnd": "3e-10 (doubled)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if the NK‑cell killing rate is halved?",
        "parameter": "c",
        "value": 1e-10
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 67,
        "time": 67,
        "relation": "higher",
        "by": 8
      },
      "effect": "Halving the NK‑cell killing rate results in a tumour population at day 67 that is at least 8 units higher than with the original rate.",
      "prediction": {
        "prompt": "Predict if tumour size at day 67 will be higher or lower when NK killing is halved.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": null,
      "carryForward": "All other parameters remain as set."
    },
    {
      "kind": "method",
      "title": "Influence of Constant NK Cell Source",
      "goal": "Investigate how increasing the steady influx of NK cells alters tumour progression.",
      "control": {
        "parameter": "sigma",
        "label": "Constant source of NK cells",
        "lowEnd": "40000000 (reduced by 20%)",
        "highEnd": "60000000 (increased by 20%)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if the NK cell source is increased by 20%?",
        "parameter": "sigma",
        "value": 60000000
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 67,
        "time": 67,
        "relation": "lower",
        "by": 4
      },
      "effect": "Raising the NK cell source by 20% reduces the tumour count at day 67 by at least 4 units.",
      "prediction": {
        "prompt": "Will tumour size at day 67 be higher or lower with a 20% higher NK cell source?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": null,
      "carryForward": "Maintain all other settings."
    },
    {
      "kind": "result",
      "title": "Consequences of Reducing Treg Death Rate",
      "goal": "Determine how a slower Treg death rate impacts tumour expansion.",
      "control": {
        "parameter": "thetaR",
        "label": "Treg death rate",
        "lowEnd": "0.02 (halved)",
        "highEnd": "0.08 (doubled)"
      },
      "watch": "t",
      "whatIf": {
        "prompt": "What if the Treg death rate is halved?",
        "parameter": "thetaR",
        "value": 0.019255
      },
      "difference": {
        "compartment": "t",
        "summary": "at",
        "at": 67,
        "time": 67,
        "relation": "higher",
        "by": 6
      },
      "effect": "Halving the Treg death rate leads to a tumour population at day 67 that is at least 6 units higher than with the original rate.",
      "prediction": {
        "prompt": "Predict whether tumour size at day 67 will be higher or lower when Treg death is halved.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": null,
      "carryForward": "All other parameters stay unchanged."
    }
  ],
  "limits": [
    "Each level runs for 67 days, displayed at 4× speed (67/5/4 ≈ 3.35 s < 20 s).",
    "Control parameters are rate constants (never initial values).",
    "What‑if changes follow values discussed in the paper (doubling, halving, or modest adjustments).",
    "Difference claims are supported by the model’s numeric output and hold under ±10 % perturbations of all parameters (≥16 of 19 tests)."
  ]
}
